From 21f5e1c91295f7befa539992bf97959cfc99a219 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:20:54 +0100
Subject: [PATCH] applets/comic: open the full-size comic on the widget's
 screen

The full-size comic window has no transient parent, so its screen was
the default first screen and it always opened centred there, whatever
screen the widget is on. Centre it on the applet's own screen instead.

BUG: 504829
---
 applets/comic/comic.cpp | 9 ++++++++-
 1 file changed, 8 insertions(+), 1 deletion(-)

diff --git a/applets/comic/comic.cpp b/applets/comic/comic.cpp
index 00e7fae38..984edc0ae 100644
--- a/applets/comic/comic.cpp
+++ b/applets/comic/comic.cpp
@@ -18,6 +18,8 @@
 #include <QWindow>

 #include <KLocalizedString>
+#include <Plasma/Containment>
+#include <Plasma/Corona>
 #include <kconfiggroup.h>

 #include "comicmodel.h"
@@ -79,7 +81,12 @@ void ComicApplet::positionFullView(QWindow *window)
         return;
     }

-    window->setPosition(window->screen()->availableGeometry().center() - QPoint(window->size().width() / 2, window->size().height() / 2));
+    QRect available = window->screen()->availableGeometry();
+    if (const Plasma::Containment *c = containment(); c && c->corona() && c->screen() >= 0) {
+        available = c->corona()->availableScreenRect(c->screen());
+    }
+
+    window->setPosition(available.center() - QPoint(window->size().width() / 2, window->size().height() / 2));
 }

 void ComicApplet::updateUsedComics()
